def c(suffix: str, subs: list[str], name: str, modes: list[str], question: str, action: str,
      unit: str, source_refs: list[str], shape_refs: list[str], evidence_refs: list[str],
      limitations: list[str] | None = None) -> dict:
    methods = list(dict.fromkeys(MODE_METHODS[m] for m in modes))
    operations = list(dict.fromkeys(op for m in modes for op in MODE_OPERATIONS[m]))
    time_model = ["event/effective time is separate from record, receipt and availability time", "all results bind a reproducible data cut"]
    if any(m in modes for m in ["prediction", "forecasting", "nowcasting"]):
        time_model.append("prediction origin, horizon, label-availability lag and backtest windows are explicit")
    if "causal_inference" in modes:
        time_model.append("eligibility, treatment assignment, time zero, follow-up and censoring are aligned")
    if any(m in modes for m in ["process_conformance", "bottleneck_analysis", "queuing_analysis"]):
        time_model.append("enabled, queued, service-start and completion timestamps are not interchangeable")
    return {
        "record_id": f"health.case.{suffix}", "record_kind": "analytical_case", "edition": 1,
        "status": "sourced_candidate", "industry_id": INDUSTRY, "subindustry_ids": subs,
        "name": name, "analytical_modes": modes, "sovereign_question": question,
        "decision_or_action": action, "actors": list(dict.fromkeys(a for s in subs for a in ACTORS[s])),
        "unit_of_analysis": unit, "population": f"In-scope {', '.join(SUBINDUSTRIES[s] for s in subs)} population under a declared eligibility, jurisdiction and observation window",
        "grain": f"one {unit} per declared version and analysis cut", "time_model": time_model,
        "source_system_refs": [f"health.source.{x}" for x in source_refs],
        "data_shape_refs": [f"health.shape.{x}" for x in shape_refs],
        "data_type_refs": ["data.health.identity_scoped", "data.health.coded_observation", "data.health.event_time_bitemporal", "data.health.uncertainty_qualified"],
        "method_refs": methods, "operation_refs": operations,
        "inputs": [f"versioned {x.replace('_', ' ')} data" for x in shape_refs] + ["eligibility, exclusions, authority, intervention/action set and loss/utility contract"],
        "outputs": [f"{name} finding or scenario with contributor/path diagnostics", "uncertainty, sensitivity, subgroup, data-fitness and refusal report", "action proposal requiring named human authority"],
        "assumptions": ["source identities, status transitions, units, terminology and correction semantics are validated before analysis", "selection, missingness, measurement error and care or activity outside observed systems are assessed", "a statistical association is not labeled a cause without an identified causal design"],
        "invariants": ["no model output independently diagnoses, treats, denies coverage, releases product or changes trial conduct", "clinical, quality, regulatory and allocation authority remain outside the analytical engine", "raw occurrences and rejected hypotheses remain traceable from every result"],
        "failure_modes": ["wrong person/specimen/device/batch linkage", "future information leakage", "status or denominator conflation", "coding and workflow drift", "automation bias", "unsupported causal attribution"],
        "evidence_refs": [f"health.evidence.{x}" for x in evidence_refs],
        "evidence_posture": "Primary sources support the workflow, data semantics or regulatory decision context; the composed analytical design is a candidate requiring domain and method review.",
        "llm_dependency": "none", "limitations": (limitations or []) + ["Local clinical policy, benefit design, protocol, product, regulator and jurisdiction can change the admissible method or action."]
    }


