    write_jsonl("sources.jsonl", SOURCES)
    write_jsonl("source-systems.jsonl", SOURCE_SYSTEMS)
    write_jsonl("data-shapes.jsonl", DATA_SHAPES)
    write_jsonl("analytics-cases.jsonl", CASES)
